UPDATE TB_EEP_HR_STAFF_M SET
	  ${FIELD} = NULLIF(#{VALUE}, ''), UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE STAFF_SQ = #{STAFF_SQ}

UPDATE TB_EEP_HR_STAFF_PRJ_R
SET PRJ_NM = #{PRJ_NM}, CLIENT_NM = #{CLIENT_NM}, WORK_NM = #{WORK_NM}, ROLE_NM = #{ROLE_NM}, START_YM = #{START_YM}, END_YM = #{END_YM,jdbcType=CHAR}
	, IND_NM = #{IND_NM}, APP_NM = #{APP_NM}, MACHINE_NM = #{MACHINE_NM}, OS_NM = #{OS_NM}, LANG_NM = #{LANG_NM}, DBMS_NM = #{DBMS_NM}, TOOL_NM = #{TOOL_NM}, FRAMEWORK_NM = #{FRAMEWORK_NM}, ETC_NM = #{ETC_NM}
	, UPDT_EMPLY_ID = #{UPDT_EMPLY_ID}, UPDT_DT = NOW()
WHERE PRJ_SQ = #{PRJ_SQ} AND STAFF_SQ = #{STAFF_SQ}
